11→class KrotalScannerController extends Controller
12→{
13→    public function index(): Response
14→    {
15→        $user = Auth::user();
16→        $exploitation = $user->exploitations()->with('subExploitations')->first();
17→
18→        return Inertia::render('scanner/index', [
19→            'exploitation' => $exploitation,
20→        ]);
21→    }
22→
23→    public function lookupByCrotal(string $code): JsonResponse
24→    {
25→        $animal = Animal::query()
26→            ->with('subExploitation')
27→            ->where('crotal_code', $code)
28→            ->first();
29→
30→        if (! $animal) {
31→            return response()->json(['message' => 'Animal no encontrado'], 404);
32→        }
33→
34→        return response()->json($animal);
35→    }
36→
37→    public function randomCrotal(): JsonResponse
38→    {
39→        $user = Auth::user();
40→
41→        $subExploitationIds = $user->exploitations()
42→            ->with('subExploitations')
43→            ->get()
44→            ->flatMap(fn ($exploitation) => $exploitation->subExploitations->pluck('id'));
45→
46→        $animal = Animal::query()
47→            ->with('subExploitation')
48→            ->whereIn('sub_exploitation_id', $subExploitationIds)
49→            ->inRandomOrder()
50→            ->first();
51→
52→        if (! $animal) {
53→            return response()->json(['message' => 'No se encontraron animales'], 404);
54→        }
55→
56→        return response()->json($animal);
57→    }
58→}
