451→function ErrorView({
452→    onRetry,
453→    onResult,
454→    initialCode = '',
455→}: {
456→    onRetry: () => void;
457→    onResult: (animal: AnimalResult) => void;
458→    initialCode?: string;
459→}) {
460→    const [code, setCode] = useState(initialCode || 'ES');
461→    const [loading, setLoading] = useState(false);
462→    const [error, setError] = useState('');
463→
464→    const searchManual = async () => {
465→        const normalized = normalizeCrotalCode(code);
466→
467→        if (!normalized) {
468→            setError('Formato inválido. Debe ser ES + 12 dígitos');
469→
470→            return;
471→        }
472→
473→        setError('');
474→        setLoading(true);
475→
476→        try {
477→            const res = await fetch(
478→                `/api/animals/by-crotal/${encodeURIComponent(normalized)}`,
479→            );
480→
481→            if (res.ok) {
482→                onResult(await res.json());
483→            } else {
484→                setError('Animal no encontrado');
485→            }
486→        } catch {
487→            setError('Error de conexión');
488→        }
489→
490→        setLoading(false);
491→    };
492→
493→    return (
494→        <div className="flex flex-col gap-5 overflow-y-auto p-6">
495→            <div className="flex flex-col items-center gap-3">
496→                <div className="flex size-16 items-center justify-center rounded-full bg-[#FFF3E0]">
497→                    <ScanSearch className="size-8 text-[#E65100]" />
498→                </div>
499→                <h2 className="text-xl font-bold">No pude leer el crotal</h2>
500→                <p className="text-center text-sm text-[#757575]">
501→                    Intentá de nuevo o ingresá el número manualmente
502→                </p>
503→            </div>
504→
505→            <button
506→                onClick={onRetry}
507→                className="flex w-full items-center justify-center gap-2 bg-[#E53935] py-[18px] text-sm font-bold text-white"
508→            >
509→                <RefreshCw className="size-4" />
510→                Intentar de nuevo
511→            </button>
512→
513→            <div className="flex flex-col gap-3 border-2 border-[#FFF8E1] bg-[#FFFDE7] p-4">
514→                <div className="flex items-center gap-2">
515→                    <Lightbulb className="size-5 text-[#F9A825]" />
516→                    <span className="text-sm font-bold">
517→                        Consejos para un mejor escaneo
518→                    </span>
519→                </div>
520→                <ul className="flex flex-col gap-2 text-xs text-[#757575]">
521→                    <li className="flex items-start gap-2">
522→                        <span className="mt-0.5 size-1.5 shrink-0 rounded-full bg-[#F9A825]" />
523→                        Limpiá el crotal con un trapo antes de escanear
524→                    </li>
525→                    <li className="flex items-start gap-2">
526→                        <span className="mt-0.5 size-1.5 shrink-0 rounded-full bg-[#F9A825]" />
527→                        Acercá el móvil a 10-15 cm del crotal
528→                    </li>
529→                    <li className="flex items-start gap-2">
530→                        <span className="mt-0.5 size-1.5 shrink-0 rounded-full bg-[#F9A825]" />
531→                        Buscá buena iluminación, evitá sombras sobre el crotal
532→                    </li>
533→                    <li className="flex items-start gap-2">
534→                        <span className="mt-0.5 size-1.5 shrink-0 rounded-full bg-[#F9A825]" />
535→                        Mantené el móvil firme y esperá a que enfoque
536→                    </li>
537→                </ul>
538→            </div>
539→
540→            <div className="flex items-center gap-3">
541→                <div className="h-px flex-1 bg-[#E0E0E0]" />
542→                <span className="text-xs text-[#9E9E9E]">o</span>
543→                <div className="h-px flex-1 bg-[#E0E0E0]" />
544→            </div>
545→
546→            <div className="flex flex-col gap-3">
547→                <p className="text-xs font-semibold tracking-[2px] uppercase">
548→                    Ingresar manualmente
549→                </p>
550→                <div className="flex gap-2">
551→                    <input
552→                        type="text"
553→                        value={code}
554→                        onChange={(e) => setCode(e.target.value.toUpperCase())}
555→                        placeholder="ES480123456789"
556→                        className="h-[52px] flex-1 bg-[#F5F5F5] px-[18px] text-sm font-medium"
557→                        maxLength={14}
558→                    />
559→                    <button
560→                        onClick={searchManual}
561→                        disabled={code.length < 10 || loading}
562→                        className="flex h-[52px] w-[52px] items-center justify-center bg-[#E53935] text-white disabled:opacity-50"
563→                    >
564→                        <Search className="size-5" />
565→                    </button>
566→                </div>
567→                <p className="text-xs text-[#9E9E9E]">
568→                    Formato: ES + 4 dígitos provincia + 3 municipio + 5
569→                    individual
570→                </p>
571→                {error && (
572→                    <p className="text-sm font-medium text-[#E53935]">
573→                        {error}
574→                    </p>
575→                )}
576→            </div>
577→        </div>
578→    );
579→}
