603→export default function ScannerIndex() {
604→    const [state, setState] = useState<ScannerState>('instructions');
605→    const [animal, setAnimal] = useState<AnimalResult | null>(null);
606→    const [lastDetectedCode, setLastDetectedCode] = useState('');
