  1→import { useCallback, useEffect, useRef, useState } from 'react';
  2→import Tesseract from 'tesseract.js';
  3→
  4→const PARTIAL_PREFIX = /ES\d{2}/i;
  5→
  6→export function normalizeCrotalCode(raw: string): string | null {
  7→    const cleaned = raw.replace(/[\s\-\n\r]/g, '').toUpperCase();
  8→    const match = cleaned.match(/ES\d{12}/);
  9→
 10→    return match ? match[0] : null;
 11→}
 12→
 13→function extractCrotalFromLines(text: string): string | null {
 14→    const direct = normalizeCrotalCode(text);
 15→
 16→    if (direct) {
 17→        return direct;
 18→    }
 19→
 20→    const lines = text
 21→        .split('\n')
 22→        .map((l) => l.trim())
 23→        .filter(Boolean);
 24→
 25→    for (let i = 0; i < lines.length; i++) {
 26→        const prefixMatch = lines[i].match(PARTIAL_PREFIX);
 27→
 28→        if (!prefixMatch) {
 29→            continue;
 30→        }
 31→
 32→        const collected = [lines[i]];
 33→
 34→        for (let j = i + 1; j < Math.min(i + 3, lines.length); j++) {
 35→            collected.push(lines[j]);
 36→        }
 37→
 38→        const combined = normalizeCrotalCode(collected.join(''));
 39→
 40→        if (combined) {
 41→            return combined;
 42→        }
 43→    }
 44→
 45→    return null;
 46→}
 47→
 48→/**
 49→ * Preprocesses a video frame for OCR:
 50→ * 1. Crops to the center ROI (scanning rectangle area)
 51→ * 2. Upscales 2x for better Tesseract accuracy
 52→ * 3. Binarizes: dark text → black, everything else → white
 53→ */
 54→function preprocessFrame(
 55→    video: HTMLVideoElement,
 56→    srcCanvas: HTMLCanvasElement,
 57→    procCanvas: HTMLCanvasElement,
 58→): void {
 59→    const vw = video.videoWidth;
 60→    const vh = video.videoHeight;
 61→
 62→    if (vw === 0 || vh === 0) {
 63→        return;
 64→    }
 65→
 66→    // Crop center ROI matching the on-screen scanning rectangle proportions
 67→    const roiW = Math.round(vw * 0.55);
 68→    const roiH = Math.round(vh * 0.45);
 69→    const roiX = Math.round((vw - roiW) / 2);
 70→    const roiY = Math.round((vh - roiH) / 2);
 71→
 72→    // Draw full frame to source canvas
 73→    srcCanvas.width = vw;
 74→    srcCanvas.height = vh;
 75→    const srcCtx = srcCanvas.getContext('2d', { willReadFrequently: true })!;
 76→    srcCtx.drawImage(video, 0, 0);
 77→
 78→    // Upscale 2x (enough for Tesseract, smaller = faster)
 79→    const scale = 2;
 80→    const outW = roiW * scale;
 81→    const outH = roiH * scale;
 82→
 83→    procCanvas.width = outW;
 84→    procCanvas.height = outH;
 85→    const ctx = procCanvas.getContext('2d', { willReadFrequently: true })!;
 86→
 87→    // Draw cropped + upscaled ROI
 88→    ctx.drawImage(srcCanvas, roiX, roiY, roiW, roiH, 0, 0, outW, outH);
 89→
 90→    // Binarize: isolate dark text from background
 91→    const imageData = ctx.getImageData(0, 0, outW, outH);
 92→    const d = imageData.data;
 93→
 94→    for (let i = 0; i < d.length; i += 4) {
 95→        const r = d[i];
 96→        const g = d[i + 1];
 97→        const b = d[i + 2];
 98→
 99→        // Luminance-weighted grayscale
100→        const gray = 0.299 * r + 0.587 * g + 0.114 * b;
101→
102→        // Threshold: dark pixels (text) → black, light pixels (background) → white
103→        const isText = gray < 130;
104→
105→        d[i] = isText ? 0 : 255;
106→        d[i + 1] = isText ? 0 : 255;
107→        d[i + 2] = isText ? 0 : 255;
108→    }
109→
110→    ctx.putImageData(imageData, 0, 0);
111→}
112→
113→export interface OcrResult {
114→    code: string | null;
115→    rawText: string;
116→}
117→
118→interface UseCrotalOcrReturn {
119→    recognizeFrame: (
120→        video: HTMLVideoElement,
121→        srcCanvas: HTMLCanvasElement,
122→        procCanvas: HTMLCanvasElement,
123→    ) => Promise<OcrResult>;
124→    isProcessing: boolean;
125→    terminate: () => void;
126→}
127→
128→export function useCrotalOcr(): UseCrotalOcrReturn {
129→    const workerRef = useRef<Tesseract.Worker | null>(null);
130→    const [isProcessing, setIsProcessing] = useState(false);
131→    const processingRef = useRef(false);
132→    const initPromiseRef = useRef<Promise<Tesseract.Worker> | null>(null);
133→
134→    const getWorker = useCallback(async (): Promise<Tesseract.Worker> => {
135→        if (workerRef.current) {
136→            return workerRef.current;
137→        }
138→
139→        if (!initPromiseRef.current) {
140→            initPromiseRef.current = (async () => {
141→                const worker = await Tesseract.createWorker('eng');
142→                await worker.setParameters({
143→                    tessedit_char_whitelist:
144→                        'REDACTED',
145→                });
146→                workerRef.current = worker;
147→
148→                return worker;
149→            })();
150→        }
151→
152→        return initPromiseRef.current;
153→    }, []);
154→
155→    // Stable reference — does not change between renders
156→    const recognizeFrame = useCallback(
157→        async (
158→            video: HTMLVideoElement,
159→            srcCanvas: HTMLCanvasElement,
160→            procCanvas: HTMLCanvasElement,
161→        ): Promise<OcrResult> => {
162→            // Use ref for guard so this callback stays stable
163→            if (processingRef.current) {
164→                return { code: null, rawText: '' };
165→            }
166→
167→            processingRef.current = true;
168→            setIsProcessing(true);
169→
170→            try {
171→                const worker = await getWorker();
172→
173→                preprocessFrame(video, srcCanvas, procCanvas);
174→
175→                const { data } = await worker.recognize(procCanvas);
176→                const code = extractCrotalFromLines(data.text);
177→
178→                return { code, rawText: data.text.replace(/\n/g, ' ').trim() };
179→            } catch (err) {
180→                console.warn('OCR recognition error:', err);
181→
182→                return { code: null, rawText: '' };
183→            } finally {
184→                processingRef.current = false;
185→                setIsProcessing(false);
186→            }
187→        },
188→        [getWorker],
189→    );
190→
191→    const terminate = useCallback(() => {
192→        workerRef.current?.terminate();
193→        workerRef.current = null;
194→        initPromiseRef.current = null;
195→    }, []);
196→
197→    useEffect(() => {
198→        return () => {
199→            terminate();
200→        };
201→    }, [terminate]);
202→
203→    return { recognizeFrame, isProcessing, terminate };
204→}
