 65→                    'sub_exploitation_id' => $subExploitation->id,
 66→                    'crotal_code' => $assignedCrotal,
 67→                    'species' => $subExploitation->species,
 68→                    'breed' => $calfData['breed'],
 69→                    'sex' => $calfData['sex'],
 70→                    'name' => $calfData['name'] ?? null,
 71→                    'birth_date' => $calfData['birth_date'],
 72→                    'mother_id' => $mother->id,
 73→                    'father_id' => $validated['father_id'] ?? null,
 74→                    'status' => 'active',
 75→                ]);
 76→
 77→                $createdCalves[] = [
 78→                    'name' => $calfData['name'] ?? null,
 79→                    'sex' => $calfData['sex'],
 80→                    'crotal' => $assignedCrotal,
 81→                ];
 82→            }
 83→
 84→            $subExploitation->increment('current_capacity', count($validated['calves']));
 85→
 86→            return redirect()->route('nacimientos.create')->with('success', [
 87→                'message' => 'Nacimiento registrado correctamente.',
 88→                'reference_code' => $referenceCode,
 89→                'calves' => $createdCalves,
 90→                'new_capacity' => $subExploitation->fresh()->current_capacity,
 91→            ]);
 92→        });
 93→    }
