 95→    /**
 96→     * Generate a mock reference code in format NC-2026-048-XXXXX.
 97→     */
 98→    private function generateReferenceCode(): string
 99→    {
100→        $year = now()->year;
101→        $sequence = str_pad((string) random_int(1, 99999), 5, '0', STR_PAD_LEFT);
102→
103→        return "NC-{$year}-048-{$sequence}";
