129→function CameraView({
130→    onResult,
131→    onError,
132→}: {
133→    onResult: (animal: AnimalResult) => void;
134→    onError: (lastDetected?: string) => void;
135→}) {
136→    const videoRef = useRef<HTMLVideoElement>(null);
137→    const srcCanvasRef = useRef<HTMLCanvasElement>(null);
138→    const procCanvasRef = useRef<HTMLCanvasElement>(null);
139→    const streamRef = useRef<MediaStream | null>(null);
140→    const [torch, setTorch] = useState(false);
141→    const [hasTorch, setHasTorch] = useState(false);
142→    const [statusText, setStatusText] = useState('Enfoca el crotal del animal');
143→    const [debugText, setDebugText] = useState('');
144→    const [showDebug, setShowDebug] = useState(false);
145→    const { recognizeFrame, isProcessing, terminate } = useCrotalOcr();
146→    const scanningRef = useRef(true);
147→    const onErrorRef = useRef(onError);
148→
149→    useEffect(() => {
150→        onErrorRef.current = onError;
151→    }, [onError]);
152→
153→    useEffect(() => {
154→        let cancelled = false;
155→
156→        (async () => {
157→            try {
158→                const stream = await navigator.mediaDevices.getUserMedia({
159→                    video: {
160→                        facingMode: 'environment',
161→                        width: { ideal: 1920 },
162→                        height: { ideal: 1080 },
163→                    },
164→                });
165→
166→                if (cancelled) {
167→                    stream.getTracks().forEach((t) => t.stop());
168→
169→                    return;
170→                }
171→
172→                streamRef.current = stream;
173→
174→                if (videoRef.current) {
175→                    videoRef.current.srcObject = stream;
176→                }
177→
178→                const track = stream.getVideoTracks()[0];
179→                const caps =
180→                    track.getCapabilities?.() as MediaTrackCapabilities & {
181→                        torch?: boolean;
182→                    };
183→
184→                if (caps?.torch) {
185→                    setHasTorch(true);
186→                }
187→            } catch {
188→                if (!cancelled) {
189→                    onErrorRef.current();
190→                }
191→            }
192→        })();
193→
194→        return () => {
195→            cancelled = true;
196→            scanningRef.current = false;
197→            streamRef.current?.getTracks().forEach((t) => t.stop());
198→            terminate();
199→        };
200→    }, [terminate]);
201→
202→    const toggleTorch = async () => {
203→        const track = streamRef.current?.getVideoTracks()[0];
204→
205→        if (track) {
206→            await track.applyConstraints({
207→                advanced: [{ torch: !torch } as MediaTrackConstraintSet],
208→            });
209→            setTorch(!torch);
210→        }
211→    };
212→
213→    const onResultRef = useRef(onResult);
214→
215→    useEffect(() => {
216→        onResultRef.current = onResult;
217→    }, [onResult]);
218→
219→    useEffect(() => {
220→        const startTime = Date.now();
221→        let active = true;
222→        let lastRawText = '';
223→
224→        const loop = async () => {
225→            while (active && scanningRef.current) {
226→                if (
227→                    !videoRef.current ||
228→                    !srcCanvasRef.current ||
229→                    !procCanvasRef.current
230→                ) {
231→                    await new Promise((r) => setTimeout(r, SCAN_INTERVAL_MS));
232→                    continue;
233→                }
234→
235→                if (Date.now() - startTime > SCAN_TIMEOUT_MS) {
236→                    scanningRef.current = false;
237→                    onErrorRef.current(lastRawText);
238→
239→                    return;
240→                }
241→
242→                setStatusText('Analizando...');
243→                const result = await recognizeFrame(
244→                    videoRef.current,
245→                    srcCanvasRef.current,
246→                    procCanvasRef.current,
247→                );
248→
249→                if (!active || !scanningRef.current) {
250→                    return;
251→                }
252→
253→                if (result.rawText) {
254→                    lastRawText = result.rawText;
255→                }
256→
257→                setDebugText(result.rawText || '(nada)');
258→
259→                if (result.code) {
260→                    scanningRef.current = false;
261→                    setStatusText('Crotal detectado, buscando animal...');
262→
263→                    try {
264→                        const res = await fetch(
265→                            `/api/animals/by-crotal/${encodeURIComponent(result.code)}`,
266→                        );
267→
268→                        if (res.ok) {
269→                            const animal = await res.json();
270→                            onResultRef.current(animal);
271→
272→                            return;
273→                        }
274→                    } catch {
275→                        /* fall through */
276→                    }
277→
278→                    onErrorRef.current(result.code);
279→                } else {
280→                    setStatusText('Enfoca el crotal del animal');
281→                }
282→
283→                await new Promise((r) => setTimeout(r, SCAN_INTERVAL_MS));
284→            }
285→        };
286→
287→        loop();
288→
289→        return () => {
290→            active = false;
291→        };
292→    }, [recognizeFrame]);
293→
294→    return (
295→        <div className="relative h-full w-full bg-[#1A1A1A]">
296→            <video
297→                ref={videoRef}
298→                autoPlay
299→                playsInline
300→                muted
301→                className="h-full w-full object-cover"
302→            />
303→            {/* Source canvas for full frame capture */}
304→            <canvas ref={srcCanvasRef} className="hidden" />
305→            {/* Processed canvas for binarized ROI — shown when debug is on */}
306→            <canvas
307→                ref={procCanvasRef}
308→                className={
309→                    showDebug
310→                        ? 'absolute bottom-20 left-2 z-50 h-24 w-40 border border-green-400'
311→                        : 'hidden'
312→                }
313→            />
314→
315→            <div className="absolute inset-0 flex items-center justify-center">
316→                <div className="relative h-48 w-72">
317→                    <div className="absolute inset-0 border-2 border-white/60" />
318→                    {isProcessing && (
319→                        <div className="absolute inset-x-0 top-0 h-0.5 animate-bounce bg-[#E53935]" />
320→                    )}
321→                </div>
322→            </div>
323→
324→            <div className="absolute inset-x-0 top-8 text-center">
325→                <p className="text-sm font-medium text-white/90">
326→                    {statusText}
327→                </p>
328→                {showDebug && debugText && (
329→                    <p className="mt-1 font-mono text-xs text-green-400">
330→                        OCR: {debugText}
331→                    </p>
332→                )}
333→            </div>
334→
335→            <div className="absolute inset-x-0 bottom-8 flex items-center justify-center gap-8">
336→                <button
337→                    onClick={() => setShowDebug((v) => !v)}
338→                    className="flex size-12 items-center justify-center bg-white/20 text-xs text-white"
339→                >
340→                    DBG
341→                </button>
342→                {hasTorch && (
343→                    <button
344→                        onClick={toggleTorch}
345→                        className="flex size-12 items-center justify-center bg-white/20 text-white"
346→                    >
347→                        {torch ? (
348→                            <Flashlight className="size-5" />
349→                        ) : (
350→                            <FlashlightOff className="size-5" />
351→                        )}
352→                    </button>
353→                )}
354→            </div>
355→        </div>
356→    );
357→}
